INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('psychische-gesundheit-arbeitsplatz-eu-kampagne-2026-2028','Psychische Gesundheit am Arbeitsplatz: EU-Kampagne startet in Österreich','Das Sozialministerium hat die EU-Kampagne für psychische Gesundheit bei der Arbeit gestartet. Der Psychologenverband BÖP begrüßt sie und fordert gesetzliche Schritte.','Psychische Gesundheit am Arbeitsplatz steht in Österreich ab sofort im Mittelpunkt einer dreijährigen EU-Kampagne. Das Sozial- und Gesundheitsministerium (BMASGPK) hat am 20. Oktober 2026 den österreichischen Startschuss für die Initiative „Gemeinsam für psychische Gesundheit bei der Arbeit“ gegeben. Getragen wird sie von der Europäischen Agentur für Sicherheit und Gesundheitsschutz am Arbeitsplatz (EU-OSHA), die Laufzeit reicht von 2026 bis 2028.

Zum Auftakt kamen Fachleute aus dem Arbeitnehmerschutz, Vertreterinnen und Vertreter der Wirtschaft sowie mehrerer Interessenvertretungen zusammen. Mit an Bord ist auch der Berufsverband Österreichischer Psychologinnen und Psychologen (BÖP), der die Kampagne in einer Aussendung vom 22. Oktober begrüßt – und zugleich weitergehende Schritte verlangt.

## Was die EU-Zahlen zeigen

Grundlage der Kampagne sind Ergebnisse der EU-OSHA-Erhebung „OSH Pulse 2025“. Sie zeichnen ein deutliches Bild der Belastungen in europäischen Betrieben:

- **44 Prozent** der Beschäftigten in der EU geben an, unter starkem Zeitdruck oder einer zu hohen Arbeitsmenge zu leiden.
- **37 Prozent** fühlen sich allgemein erschöpft.
- Bei **29 Prozent** hat die Arbeit Stress, Depressionen oder Angstzustände ausgelöst oder verschlimmert.

Damit ist fast jede dritte erwerbstätige Person in Europa von arbeitsbedingten psychischen Beschwerden betroffen. Für Unternehmen bedeutet das nicht nur ein menschliches, sondern auch ein wirtschaftliches Problem – etwa durch Krankenstände, Fluktuation und sinkende Leistungsfähigkeit.

## Psychische Gesundheit am Arbeitsplatz: Strukturen statt Einzelfälle

Der BÖP rückt in seiner Stellungnahme vor allem die Rahmenbedingungen in den Vordergrund. BÖP-Präsidentin Beate Wimmer-Puchinger verweist darauf, dass das seelische Wohlbefinden der Belegschaft eng mit Produktivität, der Bindung von Fachkräften und der Wettbewerbsfähigkeit eines Betriebs zusammenhängt. Statt Überlastung als Problem einzelner Mitarbeiterinnen und Mitarbeiter zu behandeln, sollten Arbeitsabläufe und Organisationsstrukturen selbst verbessert werden.

Eine zentrale Rolle sieht der Verband dabei bei der Arbeits- und Organisationspsychologie. Sie soll eine Verbindung zwischen der Gesundheit der Beschäftigten und dem wirtschaftlichen Erfolg herstellen. Zu ihren Aufgaben zählen laut BÖP unter anderem:

1. die Analyse von Arbeitsbedingungen sowie von Faktoren, die motivieren oder demotivieren,
2. die gemeinsame Entwicklung von Verbesserungen mit den Beschäftigten,
3. die Begleitung von Führungskräften und Teams bei Konflikten und Veränderungsprozessen,
4. Unterstützung bei der Burnout-Prävention, beim Umgang mit psychischen Belastungen, bei der Vorbeugung sexueller Belästigung und beim Aufbau einer gesundheitsförderlichen Arbeitskultur.

## Evaluierung psychischer Belastungen oft nur auf dem Papier

In Österreich sind Arbeitgeber bereits gesetzlich verpflichtet, neben körperlichen auch psychische Belastungen am Arbeitsplatz zu evaluieren. Gemeinsam mit der betrieblichen Gesundheitsförderung gilt dieses Instrument als wirksam. Nach Einschätzung des BÖP wird beides in der Praxis aber noch zu selten konsequent umgesetzt.

Die EU-Kampagne bewertet der Verband deshalb als wichtigen, aber nicht ausreichenden Schritt. Konkret fordert der BÖP zwei gesetzliche Änderungen:

- eine berufsrechtliche Verankerung der Arbeits- und Organisationspsychologie im Psychologengesetz,
- die Aufnahme der Arbeitspsychologie als dritte Säule im ArbeitnehmerInnenschutzgesetz (ASchG), neben Arbeitsmedizin und Sicherheitsfachkräften.

## Was Beschäftigte und Betriebe jetzt tun können

Für Beschäftigte, die sich dauerhaft überlastet fühlen, ist das Gespräch mit Vorgesetzten, dem Betriebsrat oder der Arbeitsmedizin ein erster Schritt. Betriebe wiederum können die verpflichtende Evaluierung nutzen, um Belastungsquellen wie Zeitdruck, unklare Zuständigkeiten oder häufige Unterbrechungen systematisch zu erfassen und gezielt zu verringern. Die Kampagne soll in den kommenden Jahren Informationsmaterial, Praxisbeispiele und Veranstaltungen bündeln, um solche Maßnahmen in Österreich stärker zu verbreiten.','gesundheit','Psyche',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/psychische-gesundheit-arbeitsplatz-eu-kampagne-2026-2028.webp','BÖP via APA-OTS','https://www.ots.at/presseaussendung/OTS_20261022_OTS0040/boep-unterstuetzt-eu-kampagne-fuer-gesunde-arbeitsplaetze','published','2026-10-22T19:45:00.000Z','2026-10-22T19:43:46.240Z','Psychische Gesundheit am Arbeitsplatz: EU-Kampagne','Psychische Gesundheit am Arbeitsplatz: EU-Kampagne läuft bis 2028. Fast jeder Dritte hat arbeitsbedingten Stress. Was der BÖP fordert – jetzt lesen.','psychische Gesundheit am Arbeitsplatz','["psychische Gesundheit am Arbeitsplatz","psychische Gesundheit Arbeit","EU-OSHA Kampagne 2026","Stress am Arbeitsplatz","Evaluierung psychischer Belastungen","Arbeitspsychologie ASchG","Burnout Prävention Betrieb","BÖP Psychologengesetz","Gemeinsam für psychische Gesundheit bei der Arbeit"]','Ruhiges Büro am Abend – Symbolbild zu psychischer Gesundheit am Arbeitsplatz','Bright modern open-plan office in Vienna in the evening, empty desks with laptops and green plants, warm desk lamps, large windows showing Viennese rooftops at dusk, calm atmosphere suggesting work-life balance, no text, no logos, no readable signs, no people','[{"q":"Was ist die EU-Kampagne zur psychischen Gesundheit bei der Arbeit?","a":"Eine Initiative der EU-OSHA unter dem Titel „Gemeinsam für psychische Gesundheit bei der Arbeit“. In Österreich hat das Sozialministerium sie am 20. Oktober 2026 gestartet, sie läuft bis 2028."},{"q":"Wie viele Beschäftigte sind betroffen?","a":"Laut EU-OSHA-Erhebung OSH Pulse 2025 hat bei 29 Prozent der Beschäftigten in der EU die Arbeit Stress, Depressionen oder Angst ausgelöst oder verstärkt; 44 Prozent berichten von starkem Zeitdruck."},{"q":"Was fordert der Psychologenverband BÖP?","a":"Die Arbeits- und Organisationspsychologie soll im Psychologengesetz verankert und als dritte Säule im ArbeitnehmerInnenschutzgesetz aufgenommen werden."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
